PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS "Owner" ("id" INTEGER NOT NULL PRIMARY KEY DEFAULT 1, "username" TEXT NOT NULL, "salt" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS "Owner_username_key" ON "Owner"("username");
CREATE TABLE IF NOT EXISTS "HostSession" ("id" TEXT NOT NULL PRIMARY KEY, "csrfHash" TEXT NOT NULL, "expiresAt" DATETIME NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "ipHash" TEXT, "userAgent" TEXT);
CREATE TABLE IF NOT EXISTS "Room" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "overlayToken" TEXT NOT NULL, "joinToken" TEXT NOT NULL, "layout" TEXT NOT NULL DEFAULT 'row', "background" TEXT NOT NULL DEFAULT 'transparent', "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS "Room_overlayToken_key" ON "Room"("overlayToken");
CREATE UNIQUE INDEX IF NOT EXISTS "Room_joinToken_key" ON "Room"("joinToken");
CREATE TABLE IF NOT EXISTS "Player" ("id" TEXT NOT NULL PRIMARY KEY, "roomId" TEXT NOT NULL, "name" TEXT NOT NULL, "accent" TEXT NOT NULL DEFAULT '#d0193c', "pinned" BOOLEAN NOT NULL DEFAULT false, "joinKey" TEXT, "idleImage" TEXT, "talkingImage" TEXT, CONSTRAINT "Player_roomId_fkey" FOREIGN KEY ("roomId") REFERENCES "Room" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX IF NOT EXISTS "Player_roomId_idx" ON "Player"("roomId");
CREATE TABLE IF NOT EXISTS "Presence" ("playerId" TEXT NOT NULL PRIMARY KEY, "present" BOOLEAN NOT NULL DEFAULT true, "speaking" BOOLEAN NOT NULL DEFAULT false, "muted" BOOLEAN NOT NULL DEFAULT false, "source" TEXT NOT NULL DEFAULT 'browser', "lastSeen" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Presence_playerId_fkey" FOREIGN KEY ("playerId") REFERENCES "Player" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE IF NOT EXISTS "AuditEvent" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "action" TEXT NOT NULL, "outcome" TEXT NOT NULL, "actor" TEXT NOT NULL, "target" TEXT, "ipHash" TEXT, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "AuditEvent_createdAt_idx" ON "AuditEvent"("createdAt");
